              type="button"
              className="inline-flex h-9 flex-1 items-center justify-center rounded-full bg-[var(--color-accent)] px-4 text-[13px] font-semibold text-[var(--color-accent-ink)] transition-colors hover:bg-[var(--color-accent-strong)]"
            >
              Follow
            </button>
          }
        />
      </div>
    </div>
  );
}

